import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int max_limit = scanner.nextInt();

        final double VERY_LARGE = 99999999.0;

        double smallest_difference = VERY_LARGE;
        int best_numerator = 0;
        int best_denominator = 1;

        for (int i = 1; i <= max_limit; ++i) {
            int candidate_num = (int) Math.round(1.0 * a * i / b - 0.0000001);
            double diff = Math.abs((1.0 * a / b) - (1.0 * candidate_num / i));
            if (diff < smallest_difference) {
                best_numerator = candidate_num;
                best_denominator = i;
                smallest_difference = diff;
            }
        }

        System.out.println(best_numerator + "/" + best_denominator);
        scanner.close();
    }
}
